const out = [];
for (const key of Object.keys(N)) {
  const [who, list] = key.split(':'); const o = old[key]; if (!o) throw new Error('no old list ' + key);
  const nw = N[key];
  nw.forEach(([mk, uk, en], i) => {
    const u = mk + ' ' + uk, e = mk + ' ' + en;
    if (i < o.length) out.push({ who, list, op: 'set', old: o[i], uk: u, en: e });
    else out.push({ who, list, op: 'add', uk: u, en: e });
  });
  for (let i = nw.length; i < o.length; i++) out.push({ who, list, op: 'del', old: o[i] });
}
for (const k in old) if (!N[k]) console.log('untouched list', k);
fs.writeFileSync(path.join(dir, 'edits_G.json'), JSON.stringify(out, null, 1));

// ---- checks: >=2 lines per tier for every thread at every step, for H and M
const tiers = mk => { const m = /^~(\d+) /.exec(mk); return m ? m[1].split('').map(Number) : [1, 2, 3]; };
const thr = mk => mk.replace(/^~\d+ /, '').slice(1);
const ans = mk => thr(mk).split('>')[0].split('|');
const nxt = mk => thr(mk).split('>')[1];
const SC = {
  intro: { open: ['хх_знайомство', 'мх_знайомство'], reply: ['хх_знайомство_відповідь', 'мх_знайомство_відповідь'], join: ['хх_знайомство_встряє', 'мх_знайомство_встряє'], close: ['хх_знайомство_кінець', 'мх_знайомство_кінець'] },
  greet: { open: ['хх_зустріч', 'мх_зустріч'], reply: ['хх_зустріч_відповідь', 'мх_зустріч_відповідь'], join: ['хх_зустріч_встряє', 'мх_зустріч_встряє'], close: ['хх_зустріч_кінець', 'мх_зустріч_кінець'] },
  rename: { open: ['хх_нове_імя', 'мх_нове_імя'], reply: ['хх_нове_імя_відповідь', 'мх_нове_імя_відповідь'], join: ['хх_нове_імя_встряє', 'мх_нове_імя_встряє'], close: ['хх_нове_імя_кінець', 'мх_нове_імя_кінець'] },
};
const L = n => N[(n.startsWith('хх') ? 'H:' : 'M:') + n];
const ANS = ['хх_до_того_хто_встряв', 'мх_до_того_хто_встряв'];
let bad = 0;
const need = (lists, t, step, sc) => { for (const n of lists) for (const tr of [1, 2, 3]) { const c = L(n).filter(x => ans(x[0]).includes(t) && tiers(x[0]).includes(tr)).length; if (c < 2) { bad++; console.log('short', sc, step, n, t, '~' + tr, c); } } };
for (const sc in SC) {
  const s = SC[sc];
  const opens = new Set(s.open.flatMap(n => L(n).map(x => ans(x[0])[0])));
  for (const t of opens) need(s.reply, t, 'reply', sc);
  const R = new Set(s.reply.flatMap(n => L(n).map(x => nxt(x[0]))));
  for (const t of R) { need(s.close, t, 'close', sc); need(s.join, t, 'join', sc); }
  const J = new Set(s.join.flatMap(n => L(n).map(x => nxt(x[0]))));
  for (const t of J) { need(s.join, t, 'D-join', sc); need(ANS, t, 'answer', sc); }
  const E = new Set(ANS.flatMap(n => L(n).filter(x => thr(x[0]).startsWith(sc + '.')).map(x => nxt(x[0]))));
  for (const t of E) need(s.close, t, 'close-after-answer', sc);
  // orphans and prefixes
  const all = [...s.open, ...s.reply, ...s.join, ...s.close].flatMap(n => L(n));
  for (const x of all) { for (const a of ans(x[0])) if (!a.startsWith(sc + '.')) { bad++; console.log('prefix', sc, x[0]); } if (/\{[^}]*\}/.test(x[1]) === false) {} }
  for (const n of s.reply) for (const x of L(n)) { if (!nxt(x[0])) { bad++; console.log('no chain', x[0], x[1]); } for (const a of ans(x[0])) if (!opens.has(a)) { bad++; console.log('orphan reply', x[0]); } }
  for (const n of s.close) for (const x of L(n)) for (const a of ans(x[0])) if (!R.has(a) && !E.has(a) && !J.has(a)) { bad++; console.log('orphan close', x[0]); }
  for (const n of s.join) for (const x of L(n)) for (const a of ans(x[0])) if (!R.has(a) && !J.has(a)) { bad++; console.log('orphan join', x[0]); }
  // questions only where the next step must answer: openings and joins (answered by the next must-step)
  for (const n of [...s.reply, ...s.close, ...ANS]) for (const x of L(n)) if (x[1].includes('?') && thr(x[0]).startsWith(sc + '.')) { bad++; console.log('question in', n, x[1]); }
}
// munin swear count, one root twice; en parity of placeholders
const sw = /(бля|курв|сук|нахуй|нахуя|хуй|хуя|хуєв|пизд|їба|гівн|срав|сра|сучар|{м_слівце}|бляха|похуй)/gi;
for (const k in N) if (k.startsWith('M:')) for (const x of N[k]) { const m = x[1].match(sw) || []; if (m.length > 2) { bad++; console.log('swears', m.length, x[1]); } }
for (const k in N) for (const x of N[k]) { const ph = s => (s.match(/\{(me|raven|addr|kin|name|friend)\}/g) || []).sort().join(); if (ph(x[1]) !== ph(x[2]) && !/\{(name|friend)\}/.test(x[1])) console.log('ph?', x[1], '|', x[2]); }
console.log('ops', out.length, 'set', out.filter(x => x.op === 'set').length, 'add', out.filter(x => x.op === 'add').length, 'del', out.filter(x => x.op === 'del').length, 'bad', bad);
